protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // 1. Discriminator property renamed: EF Core 9 defaults to "$type" instead of
    //    "Discriminator". Existing documents still use "Discriminator", so preserve it.
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // 2. ID format changed: EF Core 9 defaults to just the key value instead of
    //    "EntityType|Key". Existing documents use "Blog|1" format, so preserve it.
    modelBuilder.Entity<Blog>().Property(b => b.Id)
        .HasJsonPropertyName("id")
        .HasValueGenerator<LegacyCosmosIdGenerator>();

    // 3. HasIndex is no longer supported on the Cosmos provider (it was always a
    //    no-op). Removed to prevent InvalidOperationException at model validation.
}

